class pstring {
    unsigned int value;
public:
    pstring(const char *);
    bool operator==(const pstring &) const;
};

class vector3d {
public:
    float x;
    float y;
    float z;
};

class script_data_interface {
    void *vtable;
    void *owner;
    float num_1;
    float num_2;
    float num_3;
    float num_4;
    float num_5;
    float num_6;
    float num_7;
    float num_8;
    char strings[32];
    vector3d vec_1;
    vector3d vec_2;
public:
    bool set_ifc_vec(const pstring &att, const vector3d &val);
};

#define IFC_INTERNAL_SET_MACRO(a,b)       { static pstring pstring_set(##a##);  if(att == pstring_set)  { ##b## = val; return(true); } }

bool script_data_interface::set_ifc_vec(const pstring &att, const vector3d &val)
{
  IFC_INTERNAL_SET_MACRO("SD_VEC_1", vec_1);
  IFC_INTERNAL_SET_MACRO("SD_VEC_2", vec_2);

  return(false);
}
